   263→        if (baseDataSpan.Length > 0)
   264→        {
   265→            fixed (byte* baseData = &MemoryMarshal.GetReference(baseDataSpan))
   266→                Gmp.mpz_import(baseInt, baseLength, 1, 1, 1, nuint.Zero, (nint)baseData);
   267→        }
   268→
   269→        ReadOnlySpan<byte> expDataSpan = inputSpan.SliceWithZeroPaddingEmptyOnError(96 + (int)baseLength, (int)expLength);
   270→        if (expDataSpan.Length > 0)
   271→        {
   272→            fixed (byte* expData = &MemoryMarshal.GetReference(expDataSpan))
   273→                Gmp.mpz_import(expInt, expLength, 1, 1, 1, nuint.Zero, (nint)expData);
   274→        }
   275→
   276→        Gmp.mpz_powm(powmResult, baseInt, expInt, modulusInt);
   277→
   278→        nint powmResultLen = (nint)(Gmp.mpz_sizeinbase(powmResult, 2) + 7) / 8;
   279→        nint offset = (int)modulusLength - powmResultLen;
   280→
   281→        byte[] result = new byte[modulusLength];
   282→        fixed (byte* ptr = &MemoryMarshal.GetArrayDataReference(result))
   283→            Gmp.mpz_export((nint)(ptr + offset), out _, 1, 1, 1, nuint.Zero, powmResult);
   284→
   285→        return (result, true);
   286→    }
