                return (uint.MaxValue, uint.MaxValue, uint.MaxValue);
            }
        }
        else if (inputData.Slice(StartBaseLength, LengthSize).IndexOfAnyExcept((byte)0) >= 0 ||
                inputData.Slice(StartModLength, LengthSize).IndexOfAnyExcept((byte)0) >= 0)
