        if (expDataSpan.Length > 0)
        {
            fixed (byte* expData = &MemoryMarshal.GetReference(expDataSpan))
                Gmp.mpz_import(expInt, expLength, 1, 1, 1, nuint.Zero, (nint)expData);
        }

